async () => {
  const srcDir = "받은자료";
  const dstDir = "취소건";
  const targetFiles = ["거래-05.csv", "거래-10.csv", "거래-15.csv"];

  for (const name of targetFiles) {
    const srcPath = `${srcDir}/${name}`;
    const dstPath = `${dstDir}/${name}`;
    await t5.call("local.file", { action: "write", path: dstPath, source: srcPath, text: (await t5.call("local.file", { action: "read", path: srcPath })).text });
  }

  console.log({ ok: true, summary: "copied 취소 csv files", result: { folder: dstDir, files: targetFiles } });
}

